			// future_salts#ae500895 req_msg_id:long now:int salts:vector<future_salt> = FutureSalts;
			// not has flags

			m.SetReqMsgId(dBuf.Long())
			m.SetNow(dBuf.Int())
			// c2 := dBuf.Int()
			// if c2 != int32(CRC32_vector) {
			//     dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 2, c2)
			//     return dBuf.err
			// }
