func (m *TLBoost) Encode(x *EncodeBuf, layer int32) error {
	var encodeF = map[uint32]func() error{
		0x2a1c8c71: func() error {
			x.UInt(0x2a1c8c71)

			// set flags
			var getFlags = func() uint32 {
				var flags uint32 = 0

				if m.GetGift() == true {
					flags |= 1 << 1
				}
				if m.GetGiveaway() == true {
					flags |= 1 << 2
				}
				if m.GetUnclaimed() == true {
					flags |= 1 << 3
				}

				if m.GetUserId() != nil {
					flags |= 1 << 0
				}
				if m.GetGiveawayMsgId() != nil {
					flags |= 1 << 2
				}

				if m.GetUsedGiftSlug() != nil {
					flags |= 1 << 4
				}
				if m.GetMultiplier() != nil {
					flags |= 1 << 5
				}

				return flags
			}

			// set flags
			var flags = getFlags()
			x.UInt(flags)
			x.String(m.GetId())
			if m.GetUserId() != nil {
				x.Long(m.GetUserId().Value)
			}

			if m.GetGiveawayMsgId() != nil {
				x.Int(m.GetGiveawayMsgId().Value)
			}

			x.Int(m.GetDate())
			x.Int(m.GetExpires())
			if m.GetUsedGiftSlug() != nil {
				x.String(m.GetUsedGiftSlug().Value)
			}

			if m.GetMultiplier() != nil {
				x.Int(m.GetMultiplier().Value)
			}

			return nil
		},
	}

	clazzId := GetClazzID(Predicate_boost, int(layer))
	if f, ok := encodeF[uint32(clazzId)]; ok {
		return f()
	} else {
		// TODO(@benqi): handle error
		// log.Errorf("not found clazzId by (%s, %d)", Predicate_boost, layer)
		return nil
	}

	return nil
}

