func (m *DialogFilter) Encode(x *EncodeBuf, layer int32) error {
	predicateName := m.PredicateName
	if predicateName == "" {
		if n, ok := clazzIdNameRegisters2[int32(m.Constructor)]; ok {
			predicateName = n
		}
	}

	switch predicateName {
	case Predicate_dialogFilter:
		t := m.To_DialogFilter()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}
	case Predicate_dialogFilterDefault:
		t := m.To_DialogFilterDefault()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}
	case Predicate_dialogFilterChatlist:
		t := m.To_DialogFilterChatlist()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}

	default:
		// err := fmt.Errorf("invalid predicate error: %s",  m.PredicateName)
		// log.Errorf(err.Error())
		return nil
	}

	return nil
}

