func (m *TLMessageService) Encode(x *EncodeBuf, layer int32) error {
	var encodeF = map[uint32]func() error{
		0x2b085862: func() error {
			x.UInt(0x2b085862)

			// set flags
			var getFlags = func() uint32 {
				var flags uint32 = 0

				if m.GetOut() == true {
					flags |= 1 << 1
				}
				if m.GetMentioned() == true {
					flags |= 1 << 4
				}
				if m.GetMediaUnread() == true {
					flags |= 1 << 5
				}
				if m.GetSilent() == true {
					flags |= 1 << 13
				}
				if m.GetPost() == true {
					flags |= 1 << 14
				}
				if m.GetLegacy() == true {
					flags |= 1 << 19
				}

				if m.GetFromId() != nil {
					flags |= 1 << 8
				}

				if m.GetReplyTo() != nil {
					flags |= 1 << 3
				}

				if m.GetTtlPeriod() != nil {
					flags |= 1 << 25
				}

				return flags
			}

			// set flags
			var flags = getFlags()
			x.UInt(flags)
			x.Int(m.GetId())
			if m.GetFromId() != nil {
				m.GetFromId().Encode(x, layer)
			}

			m.GetPeerId().Encode(x, layer)
			if m.GetReplyTo() != nil {
				m.GetReplyTo().Encode(x, layer)
			}

			x.Int(m.GetDate())
			m.GetAction().Encode(x, layer)
			if m.GetTtlPeriod() != nil {
				x.Int(m.GetTtlPeriod().Value)
			}

			return nil
		},
	}

	clazzId := GetClazzID(Predicate_messageService, int(layer))
	if f, ok := encodeF[uint32(clazzId)]; ok {
		return f()
	} else {
		// TODO(@benqi): handle error
		// log.Errorf("not found clazzId by (%s, %d)", Predicate_messageService, layer)
		return nil
	}

	return nil
}

