func (m *TLPage) GetBlocks() []*PageBlock  { return m.Data2.Blocks }

func (m *TLPage) SetPhotos(v []*Photo) { m.Data2.Photos = v }
func (m *TLPage) GetPhotos() []*Photo  { return m.Data2.Photos }

