func (m *TLPage) GetViews() *wrapperspb.Int32Value  { return m.Data2.Views }

func (m *TLPage) GetPredicateName() string {
	return Predicate_page
}

func (m *TLPage) Encode(x *EncodeBuf, layer int32) error {
	var encodeF = map[uint32]func() error{
		0x98657f0d: func() error {
			x.UInt(0x98657f0d)

			// set flags
			var getFlags = func() uint32 {
				var flags uint32 = 0

				if m.GetPart() == true {
					flags |= 1 << 0
				}
				if m.GetRtl() == true {
					flags |= 1 << 1
				}
				if m.GetV2() == true {
					flags |= 1 << 2
				}

				if m.GetViews() != nil {
					flags |= 1 << 3
				}

				return flags
			}

			// set flags
			var flags = getFlags()
			x.UInt(flags)
			x.String(m.GetUrl())

			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				x.Int(int32(len(m.GetBlocks())))
				for _, v := range m.GetBlocks() {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}

			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				x.Int(int32(len(m.GetPhotos())))
				for _, v := range m.GetPhotos() {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}

			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				x.Int(int32(len(m.GetDocuments())))
				for _, v := range m.GetDocuments() {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}

			if m.GetViews() != nil {
				x.Int(m.GetViews().Value)
			}

			return nil
		},
	}

	clazzId := GetClazzID(Predicate_page, int(layer))
	if f, ok := encodeF[uint32(clazzId)]; ok {
		return f()
	} else {
		// TODO(@benqi): handle error
		// log.Errorf("not found clazzId by (%s, %d)", Predicate_page, layer)
		return nil
	}

	return nil
}

func (m *TLPage) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLPage) Decode(dBuf *DecodeBuf) error {
	var decodeF = map[uint32]func() error{
		0x98657f0d: func() error {
			var flags = dBuf.UInt()
			_ = flags
			if (flags & (1 << 0)) != 0 {
				m.SetPart(true)
			}
			if (flags & (1 << 1)) != 0 {
				m.SetRtl(true)
			}
			if (flags & (1 << 2)) != 0 {
				m.SetV2(true)
			}
			m.SetUrl(dBuf.String())
			c5 := dBuf.Int()
			if c5 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 5, c5)
				return dBuf.GetError()
			}
			l5 := dBuf.Int()
			v5 := make([]*PageBlock, l5)
			for i := int32(0); i < l5; i++ {
				v5[i] = &PageBlock{}
				v5[i].Decode(dBuf)
			}
			m.SetBlocks(v5)

			c6 := dBuf.Int()
			if c6 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 6, c6)
				return dBuf.GetError()
			}
			l6 := dBuf.Int()
			v6 := make([]*Photo, l6)
			for i := int32(0); i < l6; i++ {
				v6[i] = &Photo{}
				v6[i].Decode(dBuf)
			}
			m.SetPhotos(v6)

			c7 := dBuf.Int()
			if c7 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 7, c7)
				return dBuf.GetError()
			}
			l7 := dBuf.Int()
			v7 := make([]*Document, l7)
			for i := int32(0); i < l7; i++ {
				v7[i] = &Document{}
				v7[i].Decode(dBuf)
			}
			m.SetDocuments(v7)

			if (flags & (1 << 3)) != 0 {
				m.SetViews(&wrapperspb.Int32Value{Value: dBuf.Int()})
			}

			return dBuf.GetError()
		},
	}

	if f, ok := decodeF[uint32(m.Data2.Constructor)]; ok {
		return f()
	} else {
		return fmt.Errorf("invalid constructor: %x", uint32(m.Data2.Constructor))
	}
}

