func (m *StoryReaction) Encode(x *EncodeBuf, layer int32) error {
	predicateName := m.PredicateName
	if predicateName == "" {
		if n, ok := clazzIdNameRegisters2[int32(m.Constructor)]; ok {
			predicateName = n
		}
	}

	switch predicateName {
	case Predicate_storyReaction:
		t := m.To_StoryReaction()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}
	case Predicate_storyReactionPublicForward:
		t := m.To_StoryReactionPublicForward()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}
	case Predicate_storyReactionPublicRepost:
		t := m.To_StoryReactionPublicRepost()
		err := t.Encode(x, layer)
		if err != nil {
			return err
		}

	default:
		// err := fmt.Errorf("invalid predicate error: %s",  m.PredicateName)
		// log.Errorf(err.Error())
		return nil
	}

	return nil
}

