func (m *TLUserData) Encode(x *EncodeBuf, layer int32) error {
	var encodeF = map[uint32]func() error{
		0x1e590673: func() error {
			x.UInt(0x1e590673)

			// set flags
			var getFlags = func() uint32 {
				var flags uint32 = 0

				if m.GetProfilePhoto() != nil {
					flags |= 1 << 0
				}
				if m.GetBot() != nil {
					flags |= 1 << 8
				}

				if m.GetVerified() == true {
					flags |= 1 << 1
				}
				if m.GetSupport() == true {
					flags |= 1 << 2
				}
				if m.GetScam() == true {
					flags |= 1 << 3
				}
				if m.GetFake() == true {
					flags |= 1 << 4
				}
				if m.GetAbout() != nil {
					flags |= 1 << 5
				}
				if m.GetRestricted() == true {
					flags |= 1 << 7
				}
				if m.GetRestrictionReason() != nil {
					flags |= 1 << 7
				}

				if m.GetDeleted() == true {
					flags |= 1 << 9
				}
				if m.GetPremium() == true {
					flags |= 1 << 11
				}
				if m.GetEmojiStatus() != nil {
					flags |= 1 << 12
				}
				if m.GetStoriesUnavailable() == true {
					flags |= 1 << 13
				}
				if m.GetColor() != nil {
					flags |= 1 << 14
				}
				if m.GetProfileColor() != nil {
					flags |= 1 << 15
				}

				return flags
			}

			// set flags
			var flags = getFlags()
			x.UInt(flags)
			x.Long(m.GetId())
			x.Long(m.GetAccessHash())
			x.Int(m.GetUserType())
			x.Long(m.GetSceretKeyId())
			x.String(m.GetFirstName())
			x.String(m.GetLastName())
			x.String(m.GetUsername())
			x.String(m.GetPhone())
			if m.GetProfilePhoto() != nil {
				m.GetProfilePhoto().Encode(x, layer)
			}

			if m.GetBot() != nil {
				m.GetBot().Encode(x, layer)
			}

			x.String(m.GetCountryCode())
			if m.GetAbout() != nil {
				x.String(m.GetAbout().Value)
			}

			if m.GetRestrictionReason() != nil {
				x.Int(int32(CRC32_vector))
				{
					var (
						sz     = int32(0)
						offset = x.GetOffset()
					)
					x.Int(int32(len(m.GetRestrictionReason())))
					for _, v := range m.GetRestrictionReason() {
						err := v.Encode(x, layer)
						if err == nil {
							sz += 1
						}
					}
					x.IntOffset(offset, sz)
				}
			}
			x.Int(m.GetContactsVersion())
			x.Int(m.GetPrivaciesVersion())
			if m.GetEmojiStatus() != nil {
				m.GetEmojiStatus().Encode(x, layer)
			}

			if m.GetColor() != nil {
				m.GetColor().Encode(x, layer)
			}

			if m.GetProfileColor() != nil {
				m.GetProfileColor().Encode(x, layer)
			}

			x.Int(m.GetStoriesMaxId())
			x.String(m.GetBirthday())
			return nil
		},
	}

	clazzId := GetClazzID(Predicate_userData, int(layer))
	if f, ok := encodeF[uint32(clazzId)]; ok {
		return f()
	} else {
		// TODO(@benqi): handle error
		// log.Errorf("not found clazzId by (%s, %d)", Predicate_userData, layer)
		return nil
	}

	return nil
}

