func (m *TLContactsSetBlocked) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0x94c65c76:
		x.UInt(0x94c65c76)

		// set flags
		var flags uint32 = 0

		if m.GetMyStoriesFrom() == true {
			flags |= 1 << 0
		}

		x.UInt(flags)

		// flags Debug by @benqi

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			x.Int(int32(len(m.GetId())))
			for _, v := range m.GetId() {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		x.Int(m.GetLimit())

	default:
		// log.Errorf("")
	}

	return nil
}

