// TLChannelsUpdateColor
// /////////////////////////////////////////////////////////////////////////////
func (m *TLChannelsUpdateColor) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0xd8aa3671:
		x.UInt(0xd8aa3671)

		// set flags
		var flags uint32 = 0

		if m.GetForProfile() == true {
			flags |= 1 << 1
		}

		if m.GetColor_FLAGINT32() != nil {
			flags |= 1 << 2
		}
		if m.GetBackgroundEmojiId() != nil {
			flags |= 1 << 0
		}

		x.UInt(flags)

		// flags Debug by @benqi
		m.GetChannel().Encode(x, layer)
		if m.GetColor_FLAGINT32() != nil {
			x.Int(m.GetColor_FLAGINT32().Value)
		}

		if m.GetBackgroundEmojiId() != nil {
			x.Long(m.GetBackgroundEmojiId().Value)
		}

	case 0x621a201f:
		x.UInt(0x621a201f)

		// set flags
		var flags uint32 = 0

		if m.GetBackgroundEmojiId() != nil {
			flags |= 1 << 0
		}

		x.UInt(flags)

		// flags Debug by @benqi
		m.GetChannel().Encode(x, layer)
		x.Int(m.GetColor_INT32())
		if m.GetBackgroundEmojiId() != nil {
			x.Long(m.GetBackgroundEmojiId().Value)
		}

	default:
		// log.Errorf("")
	}

	return nil
}

func (m *TLChannelsUpdateColor) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLChannelsUpdateColor) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Constructor) {
	case 0xd8aa3671:

		flags := dBuf.UInt()
		_ = flags

		// flags Debug by @benqi
		if (flags & (1 << 1)) != 0 {
			m.ForProfile = true
		}

		m3 := &InputChannel{}
		m3.Decode(dBuf)
		m.Channel = m3

		if (flags & (1 << 2)) != 0 {
			m.Color_FLAGINT32 = &wrapperspb.Int32Value{Value: dBuf.Int()}
		}

		if (flags & (1 << 0)) != 0 {
			m.BackgroundEmojiId = &wrapperspb.Int64Value{Value: dBuf.Long()}
		}

		return dBuf.GetError()
	case 0x621a201f:

		flags := dBuf.UInt()
		_ = flags

		// flags Debug by @benqi

		m2 := &InputChannel{}
		m2.Decode(dBuf)
		m.Channel = m2

		m.Color_INT32 = dBuf.Int()
		if (flags & (1 << 0)) != 0 {
			m.BackgroundEmojiId = &wrapperspb.Int64Value{Value: dBuf.Long()}
		}

		return dBuf.GetError()

	default:
		// log.Errorf("")
	}
	return dBuf.GetError()
}

