// TLBotsSetBotCommands
// /////////////////////////////////////////////////////////////////////////////
func (m *TLBotsSetBotCommands) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0x517165a:
		x.UInt(0x517165a)

		// no flags

		m.GetScope().Encode(x, layer)
		x.String(m.GetLangCode())

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			x.Int(int32(len(m.GetCommands())))
			for _, v := range m.GetCommands() {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

	default:
		// log.Errorf("")
	}

	return nil
}

func (m *TLBotsSetBotCommands) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLBotsSetBotCommands) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Constructor) {
	case 0x517165a:

		// not has flags

		m1 := &BotCommandScope{}
		m1.Decode(dBuf)
		m.Scope = m1

		m.LangCode = dBuf.String()
		c3 := dBuf.Int()
		if c3 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 3, c3)
			return dBuf.GetError()
		}
		l3 := dBuf.Int()
		v3 := make([]*BotCommand, l3)
		for i := int32(0); i < l3; i++ {
			v3[i] = &BotCommand{}
			v3[i].Decode(dBuf)
		}
		m.Commands = v3

		return dBuf.GetError()

	default:
		// log.Errorf("")
	}
	return dBuf.GetError()
}

