func (m *TLPhoneGetGroupParticipants) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0xc558d8ab:
		x.UInt(0xc558d8ab)

		// no flags

		m.GetCall().Encode(x, layer)

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			x.Int(int32(len(m.GetIds())))
			for _, v := range m.GetIds() {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		x.VectorInt(m.GetSources())

		x.String(m.GetOffset())
		x.Int(m.GetLimit())

	default:
		// log.Errorf("")
	}

	return nil
}

