		m.Call = m1

		c2 := dBuf.Int()
		if c2 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 2, c2)
			return dBuf.GetError()
		}
		l2 := dBuf.Int()
		v2 := make([]*InputPeer, l2)
		for i := int32(0); i < l2; i++ {
			v2[i] = &InputPeer{}
			v2[i].Decode(dBuf)
		}
		m.Ids = v2

		m.Sources = dBuf.VectorInt()

